H = 3600 * 1000
TR_OFFSET_MS = 3 * H  # Istanbul UTC+3 (DST yok)

MONTHS = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"]
ARXIV_KW = ["llm", "language model", "agent", "agentic", "rag", "retrieval", "multimodal", "vision",
            "diffusion", "transformer", "reasoning", "benchmark", "fine-tun", "instruction", "alignment",
            "safety", "speech", "vector", "tool use", "planning", "embedding"]


def days_from_civil(y, m, d):
    if m <= 2:
        y -= 1
    era = (y if y >= 0 else y - 399) // 400
    yoe = y - era * 400
    doy = (153 * (m + (-3 if m > 2 else 9)) + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468


def civil_from_days(z):
    z += 719468
    era = (z if z >= 0 else z - 146096) // 146097
    doe = z - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    y = yoe + era * 400
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    d = doy - (153 * mp + 2) // 5 + 1
    m = mp + (3 if mp < 10 else -9)
    if m <= 2:
        y += 1
    return y, m, d


def fmt_istanbul(ms):
    t = int(ms // 1000) + TR_OFFSET_MS // 1000
    y, m, d = civil_from_days(t // 86400)
    sec = t % 86400
    return "%04d-%02d-%02d %02d:%02d" % (y, m, d, sec // 3600, (sec % 3600) // 60)


def offset_minutes(z):
    z = z.strip()
    if not z or z.upper() in ("Z", "GMT", "UT", "UTC"):
        return 0
    if z[0] in "+-":
        digits = z[1:].replace(":", "")
        mins = int(digits[0:2]) * 60 + (int(digits[2:4]) if len(digits) >= 4 else 0)
        return -mins if z[0] == "-" else mins
    return 0


def parse_iso(s):
    y, m, d = int(s[0:4]), int(s[5:7]), int(s[8:10])
    hh = int(s[11:13]) if len(s) >= 13 else 0
    mm = int(s[14:16]) if len(s) >= 16 else 0
    ss = int(s[17:19]) if (len(s) >= 19 and s[16] == ":") else 0
    tail = s[19:] if len(s) > 19 else ""
    pos = max(tail.rfind("+"), tail.rfind("-"))
    off = offset_minutes(tail[pos:]) if pos >= 0 else 0
    return (days_from_civil(y, m, d) * 86400 + hh * 3600 + mm * 60 + ss - off * 60) * 1000


def parse_rfc822(s):
    parts = s.replace(",", " ").split()
    if parts and not parts[0][0].isdigit():
        parts = parts[1:]
    d = int(parts[0])
    m = MONTHS.index(parts[1][:3].lower()) + 1
    y = int(parts[2])
    hh = mm = ss = 0
    if len(parts) > 3:
        tp = parts[3].split(":")
        hh = int(tp[0])
        mm = int(tp[1]) if len(tp) > 1 else 0
        ss = int(tp[2]) if len(tp) > 2 else 0
    off = offset_minutes(parts[4]) if len(parts) > 4 else 0
    return (days_from_civil(y, m, d) * 86400 + hh * 3600 + mm * 60 + ss - off * 60) * 1000


def parse_ms(s):
    s = str(s or "").strip()
    if not s:
        return None
    try:
        if len(s) >= 10 and s[:4].isdigit() and s[4] == "-":
            return parse_iso(s)
        return parse_rfc822(s)
    except Exception:
        return None


def norm_link(u):
    s = str(u or "").lower()
    if s.startswith("https://"):
        s = s[8:]
    elif s.startswith("http://"):
        s = s[7:]
    if s.startswith("www."):
        s = s[4:]
    s = s.split("#")[0].split("?")[0]
    return s.rstrip("/")


def norm_title(t):
    out = []
    for ch in str(t or "").lower():
        out.append(ch if ("a" <= ch <= "z" or "0" <= ch <= "9") else " ")
    return " ".join("".join(out).split())


def strip(s):
    out = []
    in_tag = False
    for ch in str(s or ""):
        if ch == "<":
            in_tag = True
            out.append(" ")
        elif ch == ">" and in_tag:
            in_tag = False
        elif not in_tag:
            out.append(ch)
    return " ".join("".join(out).split())


def source_of(link):
    if "arxiv.org" in link:
        return "arXiv cs.AI"
    if "openai.com" in link:
        return "OpenAI"
    if "deepmind" in link:
        return "Google DeepMind"
    if "huggingface.co" in link:
        return "Hugging Face"
    if "blog.google" in link:
        return "Google AI Blog"
    return "Diger"


def clean_arxiv_snippet(s):
    if s[:6].lower() == "arxiv:":
        idx = s.lower().find("abstract:")
        if 0 <= idx < 100:
            return s[idx + 9:].lstrip()
    return s


rows = [it["json"] for it in _items]

now_ms = None
run_date = None
sent_raw = ""
for j in rows:
    if j.get("nowMs") is not None:
        now_ms = j.get("nowMs")
        run_date = j.get("runDate")
        sent_raw = j.get("sentKeys") or ""
        break
try:
    now_ms = float(now_ms)
except Exception:
    now_ms = None
sent = set(k for k in str(sent_raw).split("\n") if k)

source_errors = []
ok_sources = set()
seen_links = set()
seen_titles = set()
all_items = []
fetched = 0

for j in rows:
    if j.get("error"):
        err = j["error"]
        msg = err.get("message") if isinstance(err, dict) and err.get("message") else err
        source_errors.append("RSS: " + str(msg)[:120])
        continue
    if not j.get("title") or not j.get("link"):
        continue
    fetched += 1
    link = str(j["link"])
    source = source_of(link)
    ok_sources.add(source)
    snippet_raw = strip(j.get("contentSnippet") or j.get("content") or j.get("summary") or "")
    if source == "arXiv cs.AI":
        low = snippet_raw.lower().replace("announce type: ", "announce type:")
        if ("announce type:replace" in low or "announce type:cross-list" in low) and "announce type:new" not in low:
            continue
        hay = (str(j["title"]) + " " + snippet_raw[:400]).lower()
        if not any(k in hay for k in ARXIV_KW):
            continue
    ms = parse_ms(j.get("isoDate") or j.get("pubDate") or "")
    all_items.append((j, link, source, snippet_raw, ms))

if now_ms is None:
    dated = [x[4] for x in all_items if x[4] is not None]
    now_ms = max(dated) if dated else 0
if not run_date:
    run_date = fmt_istanbul(now_ms)[:10]

cands = []
for j, link, source, snippet_raw, ms in all_items:
    has_date = ms is not None
    age_h = (now_ms - ms) / H if has_date else None
    if has_date and age_h > 24 * 7:
        continue
    key = norm_link(link)
    t_key = norm_title(j["title"])
    if key in sent or key in seen_links or t_key in seen_titles:
        continue
    seen_links.add(key)
    seen_titles.add(t_key)
    snippet = clean_arxiv_snippet(snippet_raw) if source == "arXiv cs.AI" else snippet_raw
    cands.append({
        "source": source,
        "title": strip(j["title"]),
        "link": link,
        "key": key,
        "ms": ms if has_date else 0,
        "published": fmt_istanbul(ms) if has_date else "Tarih dogrulanamadi",
        "ageHours": int((age_h + 0.5) // 1) if has_date else None,
        "snippet": snippet[:600],
    })

cands.sort(key=lambda x: -x["ms"])
window_used = "72 saat"
pool = [x for x in cands if x["ageHours"] is not None and x["ageHours"] <= 72]
if len(pool) < 5:
    pool = [x for x in cands if x["ageHours"] is None or x["ageHours"] <= 24 * 7]
    window_used = "7 gun"
arxiv = [x for x in pool if x["source"] == "arXiv cs.AI"][:10]
others = [x for x in pool if x["source"] != "arXiv cs.AI"][:25]
items = [{"id": "N" + str(i + 1), **x} for i, x in enumerate(others + arxiv)]

return [{"json": {
    "runDate": run_date,
    "windowUsed": window_used,
    "fetchedCount": fetched,
    "items": items,
    "okSources": list(ok_sources),
    "sourceErrors": source_errors,
}}]

