const H = 3600 * 1000;
const nowMs = Date.now();
const srcs = $('Job Sources').all().map(i => i.json);
let sent = new Set();
try { sent = new Set($('Load Sent History1').all().map(i => i.json.item_key).filter(Boolean)); } catch (e) {}

function decode(s) { return String(s || '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&'); }
function strip(s) { return decode(decode(s).replace(/<[^>]*>/g, ' ')).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim(); }
function normLink(u) { return String(u || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('#')[0].split('?')[0].replace(/\/+$/, ''); }
function normText(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9çğıöşü]+/g, ' ').trim(); }
function arr(v) { return Array.isArray(v) ? v : (v ? [v] : []); }

// English + Turkish role keywords
const roleRe = /(\bai\b|\ba\.i\.|artificial intelligence|machine learning|machine-learning|\bml\b|deep learning|data scien|computer vision|\bnlp\b|natural language|\bllm|generative|gen ?ai|ai agent|ai engineer|automation engineer|research engineer|research intern|mlops|ki-|künstliche intelligenz|yapay zek|makine öğren|derin öğren|veri bilim|görüntü işleme|doğal dil)/i;
const pyRe = /python/i;
const mlCtx = /(machine learning|\bml\b|\bai\b|deep learning|pytorch|tensorflow|llm|data scien|computer vision|nlp|yapay zek|makine öğren)/i;
const trRe = /(turkey|türkiye|turkiye|istanbul|İstanbul|ankara|izmir|İzmir|kocaeli|bursa|antalya|eskişehir|eskisehir|konya|kayseri|gebze)/i;
const trRemoteRe = /(worldwide|anywhere|global|turkey|türkiye|turkiye|emea|europe)/i;

function level(title, types) {
  const t = (title + ' ' + types).toLowerCase();
  if (/(\bintern\b|internship|praktikum|praktikant|stajyer|\bstaj\b|stagiaire|trainee|\bstage\b)/.test(t)) return 'Internship';
  if (/(werkstudent|working student|part[_ -]?time|teilzeit|yarı zamanlı)/.test(t)) return 'Part-time';
  if (/(new grad|graduate|absolvent|entry-level|entry level|yeni mezun)/.test(t)) return 'New Graduate';
  if (/(junior|jr\.?\b|associate)/.test(t)) return 'Junior';
  if (/(senior|sr\.?\b|lead|principal|staff|head of|director|manager|architect|kıdemli)/.test(t)) return 'Senior';
  return 'Mid / Belirtilmemis';
}

const sourceErrors = [];
const okSources = new Set();
const stats = {};
function stat(name) { if (!stats[name]) stats[name] = { fetched: 0, matched: 0, picked: 0 }; return stats[name]; }
const raw = [];
function add(r) { raw.push(r); stat(r.source).fetched++; }

$input.all().forEach(it => {
  const j = it.json || {};
  const idx = it.pairedItem && typeof it.pairedItem.item === 'number' ? it.pairedItem.item : -1;
  const s = srcs[idx] || {};
  const leverNames = { trendyol: 'Trendyol', insiderone: 'Insider', dreamgames: 'Dream Games', peakgames: 'Peak' };
  const isLever = !!(j.text && j.hostedUrl);
  const type = isLever ? 'lever' : (s.type || (Array.isArray(j.data) ? 'arbeitnow' : 'remotive'));
  const leverSlug = isLever ? (String(j.hostedUrl).split('jobs.lever.co/')[1] || '').split('/')[0] : '';
  const leverCo = leverNames[leverSlug] || leverSlug;
  const name = isLever ? leverCo + ' Kariyer' : (s.source || type);
  if (j.error) { sourceErrors.push(name + ': ' + String(j.error.message || j.error).slice(0, 120)); return; }
  if (type === 'lever') {
    if (!j.text || !j.hostedUrl) return;
    okSources.add(name);
    const c = j.categories || {};
    const locs = arr(c.allLocations).length ? arr(c.allLocations).join(' / ') : (c.location || 'belirtilmemis');
    add({
      source: name, title: j.text, company: leverCo, url: j.hostedUrl, geo: locs,
      location: locs + (j.workplaceType === 'remote' ? ' / Remote' : (j.workplaceType === 'hybrid' ? ' / Hibrit' : '')),
      remote: j.workplaceType === 'remote', trRemote: false, types: String(c.commitment || ''),
      ms: Number(j.createdAt), desc: j.descriptionPlain || j.description, tags: String(c.team || ''), salary: '', maxAgeDays: 90,
    });
  } else if (type === 'himalayas' && Array.isArray(j.jobs)) {
    okSources.add(name);
    j.jobs.forEach(x => {
      const restr = arr(x.locationRestrictions);
      const openTr = restr.length === 0 || restr.indexOf('Turkey') >= 0;
      const loc = restr.length === 0 ? 'Remote (Dünya geneli)' : (restr.indexOf('Turkey') >= 0 ? 'Remote (Türkiye dahil)' : 'Remote (' + restr.slice(0, 3).join(', ') + ')');
      add({
        source: name, title: x.title, company: x.companyName, url: x.applicationLink || x.guid,
        location: loc, remote: true, trRemote: openTr,
        types: arr(x.seniority).join(', ') + (x.employmentType ? ', ' + x.employmentType : ''),
        ms: x.pubDate ? Number(x.pubDate) * 1000 : NaN, desc: x.description || x.excerpt, tags: arr(x.categories).slice(0, 5).join(', '), salary: '', maxAgeDays: 14,
      });
    });
  } else if (type === 'jobicy' && Array.isArray(j.jobs)) {
    okSources.add(name);
    j.jobs.forEach(x => add({
      source: name, title: x.jobTitle, company: x.companyName, url: x.url,
      location: 'Remote (' + (x.jobGeo || 'belirtilmemis') + ')', remote: true, trRemote: trRemoteRe.test(String(x.jobGeo || '')),
      types: String(x.jobLevel || '') + ', ' + arr(x.jobType).join(', '),
      ms: Date.parse(x.pubDate || ''), desc: x.jobDescription || x.jobExcerpt, tags: arr(x.jobIndustry).join(', '), salary: '', maxAgeDays: 14,
    }));
  } else if (type === 'arbeitnow' && Array.isArray(j.data)) {
    okSources.add(name);
    j.data.forEach(x => add({
      source: name, title: x.title, company: x.company_name, url: x.url, geo: x.location || '',
      location: (x.location || 'belirtilmemis') + (x.remote ? ' / Remote' : ''),
      remote: !!x.remote, trRemote: false, types: arr(x.job_types).join(', '),
      ms: x.created_at ? Number(x.created_at) * 1000 : NaN, desc: x.description, tags: arr(x.tags).join(', '), salary: '', maxAgeDays: 14,
    }));
  } else if (Array.isArray(j.jobs)) {
    okSources.add(name);
    j.jobs.forEach(x => add({
      source: name, title: x.title, company: x.company_name, url: x.url,
      location: 'Remote (' + (x.candidate_required_location || 'belirtilmemis') + ')',
      remote: true, trRemote: trRemoteRe.test(String(x.candidate_required_location || '')), types: String(x.job_type || ''),
      ms: Date.parse(x.publication_date || ''), desc: x.description, tags: arr(x.tags).join(', '), salary: x.salary || '', maxAgeDays: 14,
    }));
  }
});

const seen = new Set();
const out = [];
raw.forEach(r => {
  if (!r.title || !r.url) return;
  const desc = strip(r.desc);
  const isRole = roleRe.test(r.title) || (pyRe.test(r.title) && mlCtx.test(desc.slice(0, 3000)));
  if (!isRole) return;
  const hasDate = !isNaN(r.ms) && r.ms > 0;
  const ageH = hasDate ? (nowMs - r.ms) / H : null;
  if (hasDate && ageH > 24 * r.maxAgeDays) return;
  const key = normLink(r.url);
  const dupKey = normText(r.title) + '|' + normText(r.company);
  if (sent.has(key) || seen.has(key) || seen.has(dupKey)) return;
  seen.add(key); seen.add(dupKey);
  const lvl = level(r.title, r.types);
  const inTr = trRe.test(r.geo || '');
  const entry = ['Internship', 'Part-time', 'New Graduate', 'Junior'].includes(lvl);
  // Priority: 1) Turkey + entry level, 2) Turkey AI/ML, 3) remote open to Turkey, 4) international
  let score = 0;
  if (inTr) score += 150; else if (r.trRemote) score += 50;
  if (entry) score += 40;
  if (lvl === 'Senior') score -= 30;
  if (hasDate && ageH <= 72) score += 10;
  if (/\b(usa|us only|united states|canada)\b/i.test(r.location)) score -= 15;
  stat(r.source).matched++;
  out.push({
    source: r.source, title: strip(r.title), company: r.company || 'Belirtilmemis', location: r.location,
    link: r.url, key: key, level: lvl, jobType: r.types, salary: r.salary,
    published: hasDate ? DateTime.fromMillis(r.ms).setZone('Europe/Istanbul').toFormat('yyyy-MM-dd') : 'Tarih dogrulanamadi',
    ageHours: hasDate ? Math.round(ageH) : null,
    turkey: inTr, turkeyRemote: !inTr && !!r.trRemote, priority: inTr && entry ? 1 : (inTr ? 2 : (r.trRemote ? 3 : 4)),
    score: score, tags: r.tags,
    snippet: desc.slice(0, 700),
  });
});
out.sort((a, b) => (b.score - a.score) || ((a.ageHours === null ? 99999 : a.ageHours) - (b.ageHours === null ? 99999 : b.ageHours)));
let seniors = 0;
const picked = [];
out.forEach(x => {
  if (picked.length >= 25) return;
  if (x.level === 'Senior') { if (seniors >= 4) return; seniors++; }
  picked.push(x);
  stat(x.source).picked++;
});
const items = picked.map((x, i) => Object.assign({ id: 'J' + (i + 1) }, x));
return [{ json: {
  fetchedCount: raw.length,
  matchedCount: out.length,
  items: items,
  sourceStats: stats,
  okSources: Array.from(okSources),
  sourceErrors: sourceErrors,
} }];

function safe(fn, d) { try { const v = fn(); return (v === undefined || v === null) ? d : v; } catch (e) { return d; } }
function esc(s) { return String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function aiOut(name) {
  return safe(() => {
    const j = $(name).first().json;
    if (!j || j.error || !Array.isArray(j.output)) return null;
    const msg = j.output.find(o => o.type === 'message') || j.output[0];
    let t = msg.content[0].text;
    if (typeof t === 'string') t = JSON.parse(t);
    return t;
  }, null);
}
const runDate = $now.setZone('Europe/Istanbul').toFormat('yyyy-MM-dd');
const news = safe(() => $('Prepare News').first().json, { items: [], sourceErrors: ['Haber akisi calismadi'], okSources: [] });
const jobs = safe(() => $('Prepare Jobs').first().json, { items: [], sourceErrors: ['Ilan akisi calismadi'], okSources: [] });
const newsAi = aiOut('Summarize News (TR)');
const jobsAi = aiOut('Analyze Jobs (TR)');
const notes = [];
const sentRows = [];



// ---- News ----
const newsById = {};
(news.items || []).forEach(n => { newsById[n.id] = n; });
let newsList = [];
if (newsAi && Array.isArray(newsAi.items) && newsAi.items.some(a => newsById[a.id])) {
  newsList = newsAi.items.filter(a => newsById[a.id]).sort((a, b) => (b.importance || 0) - (a.importance || 0)).slice(0, 10).map(a => {
    const n = newsById[a.id];
    sentRows.push({ item_key: n.key, item_type: 'news', title: n.title.slice(0, 250) });
    (a.merged_ids || []).forEach(m => { if (newsById[m]) sentRows.push({ item_key: newsById[m].key, item_type: 'news', title: newsById[m].title.slice(0, 250) }); });
    return { title: a.title_tr || n.title, orig: n.title, source: n.source, published: n.published, ageHours: n.ageHours, summary: a.summary_tr, why: a.why_important, use: a.use_case, cat: a.category, link: n.link };
  });
} else if ((news.items || []).length) {
  notes.push('AI ozetleme adimi calismadi; haberler ozetsiz, orijinal basliklariyla listelendi.');
  newsList = news.items.slice(0, 10).map(n => {
    sentRows.push({ item_key: n.key, item_type: 'news', title: n.title.slice(0, 250) });
    return { title: n.title, orig: '', source: n.source, published: n.published, ageHours: n.ageHours, summary: 'AI ozeti uretilemedi. Kaynak aciklamasi: ' + (n.snippet || 'yok').slice(0, 250), why: '', use: '', cat: '', link: n.link };
  });
}

// ---- Jobs ----
const jobById = {};
(jobs.items || []).forEach(j => { jobById[j.id] = j; });
let jobList = [];
const aiJobMap = {};
if (jobsAi && Array.isArray(jobsAi.jobs)) jobsAi.jobs.forEach(a => { aiJobMap[a.id] = a; });
else if ((jobs.items || []).length) notes.push('AI ilan analizi calismadi; beceri ve sart alanlari bos birakildi.');
(jobs.items || []).forEach(j => {
  const a = aiJobMap[j.id];
  if (a && a.relevant === false) return;
  sentRows.push({ item_key: j.key, item_type: 'job', title: (j.title + ' @ ' + j.company).slice(0, 250) });
  jobList.push({ title: j.title, company: j.company, location: j.location, published: j.published, ageHours: j.ageHours, level: (a && a.level) || j.level, skills: (a && a.skills) || [], req: (a && a.requirements_tr) || '', link: j.link, source: j.source, turkey: j.turkey });
});
if (!jobList.some(j => j.turkey)) notes.push('Bugun kullanilan kaynaklarda Turkiye lokasyonlu yeni ilan bulunamadi (Remotive ve Arbeitnow agirlikli olarak uzaktan/Avrupa ilanlari icerir).');

// ---- HTML ----
const C = { wrap: 'max-width:640px;margin:0 auto;font-family:Arial,Helvetica,sans-serif;color:#1f2937;line-height:1.5;font-size:15px;', h2: 'font-size:19px;margin:28px 0 10px;padding-bottom:6px;border-bottom:2px solid #4f46e5;color:#111827;', card: 'border:1px solid #e5e7eb;border-radius:10px;padding:14px;margin:0 0 12px;background:#ffffff;', meta: 'font-size:12px;color:#6b7280;margin:2px 0 8px;', a: 'color:#4f46e5;font-weight:bold;text-decoration:none;', small: 'font-size:13px;margin:4px 0;' };
function age(h) { if (h === null || h === undefined) return ''; if (h < 24) return ' (' + h + ' saat once)'; return ' (' + Math.round(h / 24) + ' gun once)'; }
const P = [];
P.push('<div style="background:#f3f4f6;padding:12px 8px;"><div style="' + C.wrap + '">');
P.push('<div style="background:#4f46e5;color:#fff;border-radius:10px;padding:16px;"><div style="font-size:22px;font-weight:bold;">AI Daily Digest</div><div style="font-size:13px;opacity:.9;">' + esc(runDate) + ' &middot; Europe/Istanbul</div></div>');

// Daily summary
const top3 = (newsAi && Array.isArray(newsAi.top3) && newsAi.top3.length) ? newsAi.top3.slice(0, 3) : newsList.slice(0, 3).map(n => n.title);
P.push('<div style="' + C.card + 'margin-top:12px;"><div style="font-weight:bold;margin-bottom:6px;">Gunun Ozeti</div>');
if (top3.length) { P.push('<ol style="margin:0 0 8px 18px;padding:0;">'); top3.forEach(t => P.push('<li style="' + C.small + '">' + esc(t) + '</li>')); P.push('</ol>'); }
else P.push('<div style="' + C.small + '">Bugun one cikan yeni bir AI gelismesi bulunamadi.</div>');
P.push('<div style="' + C.small + '"><b>Haber sayisi:</b> ' + newsList.length + ' &middot; <b>Yeni AI is firsati:</b> ' + jobList.length + ' (Staj/Junior/Part-time: ' + jobList.filter(j => ['Internship', 'Part-time', 'Junior', 'New Graduate'].includes(j.level)).length + ')</div>');
const alerts = [newsAi && newsAi.alert, jobsAi && jobsAi.alert].filter(x => x && String(x).trim());
alerts.forEach(al => P.push('<div style="background:#fef3c7;border-radius:6px;padding:8px;margin-top:6px;font-size:13px;"><b>Uyari:</b> ' + esc(al) + '</div>'));
P.push('</div>');

// Section 1
P.push('<h2 style="' + C.h2 + '">Bolum 1 &mdash; Gunun Yapay Zeka Gundemi</h2>');
if (news.windowUsed === '7 gun' && newsList.length) P.push('<div style="' + C.meta + '">Son 72 saatte yeterli haber olmadigi icin son 7 gun degerlendirildi; yayin tarihlerine dikkat edin.</div>');
if (!newsList.length) P.push('<div style="' + C.card + '">Bugun kaynaklarda yeni ve daha once gonderilmemis AI haberi bulunamadi.</div>');
newsList.forEach((n, i) => {
  P.push('<div style="' + C.card + '"><div style="font-weight:bold;font-size:16px;">' + (i + 1) + '. ' + esc(n.title) + '</div>');
  P.push('<div style="' + C.meta + '">' + esc(n.source) + ' &middot; ' + esc(n.published) + esc(age(n.ageHours)) + (n.cat ? ' &middot; ' + esc(n.cat) : '') + '</div>');
  if (n.orig && n.orig !== n.title) P.push('<div style="' + C.meta + '">Orijinal baslik: ' + esc(n.orig) + '</div>');
  if (n.summary) P.push('<div style="' + C.small + '">' + esc(n.summary) + '</div>');
  if (n.why) P.push('<div style="' + C.small + '"><b>Neden onemli:</b> ' + esc(n.why) + '</div>');
  if (n.use) P.push('<div style="' + C.small + '"><b>Kullanim alani:</b> ' + esc(n.use) + '</div>');
  P.push('<div style="margin-top:8px;"><a style="' + C.a + '" href="' + esc(n.link) + '">Kaynaga git &rarr;</a></div></div>');
});

// Section 2
P.push('<h2 style="' + C.h2 + '">Bolum 2 &mdash; Yeni AI Is Firsatlari</h2>');
if (!jobList.length) P.push('<div style="' + C.card + '">Bugun kriterlere uyan yeni ve daha once gonderilmemis ilan bulunamadi.</div>');
jobList.forEach((j, i) => {
  P.push('<div style="' + C.card + '"><div style="font-weight:bold;font-size:16px;">' + (i + 1) + '. ' + esc(j.title) + '</div>');
  P.push('<div style="' + C.meta + '">' + esc(j.company) + ' &middot; ' + esc(j.location) + '</div>');
  P.push('<div style="' + C.small + '"><b>Yayin:</b> ' + esc(j.published) + esc(age(j.ageHours)) + ' &middot; <b>Seviye:</b> ' + esc(j.level) + ' &middot; <b>Kaynak:</b> ' + esc(j.source) + '</div>');
  if (j.skills.length) P.push('<div style="' + C.small + '"><b>Beceriler:</b> ' + esc(j.skills.join(', ')) + '</div>');
  if (j.req) P.push('<div style="' + C.small + '"><b>Onemli sartlar:</b> ' + esc(j.req) + '</div>');
  P.push('<div style="margin-top:8px;"><a style="' + C.a + '" href="' + esc(j.link) + '">Ilana / basvuruya git &rarr;</a></div></div>');
});

// Footer
const errs = (news.sourceErrors || []).concat(jobs.sourceErrors || []);
P.push('<div style="font-size:12px;color:#6b7280;margin-top:20px;">');
P.push('<div><b>Calisan kaynaklar:</b> ' + esc((news.okSources || []).concat(jobs.okSources || []).join(', ') || 'yok') + '</div>');
if (errs.length) P.push('<div style="color:#b91c1c;"><b>Hata veren kaynaklar:</b> ' + esc(errs.join(' | ')) + '</div>');
notes.forEach(n => P.push('<div>' + esc(n) + '</div>'));
P.push('<div>Ozetler yalnizca RSS/ilan metnine dayanir; ayrintilar icin orijinal kaynaga bakin. Ilan kaynaklari: Remotive, Arbeitnow, Jobicy, Himalayas ve sirketlerin acik kariyer sayfalari (Lever). LinkedIn ve Kariyer.net acik API sunmadigi icin dahil degildir.</div>');
P.push('</div></div></div>');

return [{ json: {
  runDate: runDate,
  subject: 'AI Daily Digest | ' + runDate,
  html: P.join(''),
  newsCount: newsList.length,
  jobCount: jobList.length,
  sentRows: sentRows,
} }];

